@Override
public int read(byte[] b, int off, int len) {
    if (position >= length) {
        return -1;
    }
    int available = length - position;
    int toRead = Math.min(len, available);
    System.arraycopy(data, position, b, off, toRead);
    position += toRead;
    return toRead;
}
